        while st:
          y,x=st.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==v and (yy,xx) not in seen:
              seen.add((yy,xx)); st.append((yy,xx))
        comps.append((v,cells,min(y for y,x in cells),min(x for y,x in cells)))
    by={}
    for a in comps: by.setdefault(a[0],[]).append(a)
    for v,items in by.items():
      items.sort(key=lambda a:(a[2],a[3]))
      # Reposition into two rows: topmost copy is placed low, lower copy is placed mid.
      for i,(_,cells,r0,c0) in enumerate(items):
        nr=7 if i==0 else 4
        nc=0 if c0<5 else 5
        for y,x in cells:
          yy=nr+y-r0; xx=nc+x-c0
          if 0<=yy<h and 0<=xx<w: out[yy][xx]=v
    return out
